Switch Deep & Duff's Device:
#include <stdio.h>

// Duff's Device: unrolled loop via switch
void send_buffer(char *to, char *from, int count) {
    int n = (count + 7) / 8;
    switch (count % 8) {
        case 0: do { *to++ = *from++;
        case 7:      *to++ = *from++;
        case 6:      *to++ = *from++;
        case 5:      *to++ = *from++;
        case 4:      *to++ = *from++;
        case 3:      *to++ = *from++;
        case 2:      *to++ = *from++;
        case 1:      *to++ = *from++;
        } while (--n > 0);
    }
}

int main() {
    char src[] = "Hello World";
    char dst[12] = {0};
    send_buffer(dst, src, 11);
    printf("%s\n", dst);

    // Fallthrough annotation (C23)
    int val = 2;
    switch (val) {
        case 1:
        case 2:  // intentional fallthrough
            puts("One or two");
            break;
        case 3:
            puts("Three");
            [[fallthrough]];  // C23 explicit
        default:
            puts("Other");
    }

    return 0;
}

