int main() {
    int n = 5;
    int vla[n];  // runtime-size array
    for (int i = 0; i < n; i++)
        vla[i] = i * i;

    printf("sizeof(vla) = %zu\n", sizeof(vla));  // runtime eval

    // 2D VLA
    int rows = 3, cols = 4;
    int grid[rows][cols];
    for (int i = 0; i < rows; i++)
        for (int j = 0; j < cols; j++)
            grid[i][j] = i * cols + j;

    print_matrix(rows, cols, grid);

    // Caution: large VLAs cause stack overflow
    // size_t too_big = 100000000;
