#include <stdio.h>
#include <stdint.h>

// Bit field struct — compact flags
struct Flags {
    unsigned int active : 1;    // 1 bit
    unsigned int visible : 1;   // 1 bit
    unsigned int type    : 2;   // 2 bits (0-3)
    unsigned int : 0;            // zero-width: align to next unit
    unsigned int id      : 8;   // 8 bits
};

// Packed struct — no padding
struct __attribute__((packed)) Packet {
    uint8_t  version : 4;
    uint8_t  type    : 4;
    uint16_t length;
    uint32_t payload;
};

