    // Formatted date/time
    struct tm *local = localtime(&now);
    char buf[64];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", local);
    printf("Local time: %s\n", buf);

    // Parsing
    struct tm parsed = {0};
    strptime("2024-01-15", "%Y-%m-%d", &parsed);  // POSIX, not C standard
    printf("Parsed year: %d\n", parsed.tm_year + 1900);

    // Timing code
    clock_t start = clock();
    volatile unsigned long sum = 0;
    for (int i = 0; i < 100000000; i++) sum += i;
    clock_t end = clock();

    double elapsed = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Elapsed: %.3f seconds\n", elapsed);

    // C11: timespec
    struct timespec ts;
    timespec_get(&ts, TIME_UTC);
    printf("ns: %ld\n", ts.tv_nsec);

    return 0;
}

