struct SafeStr {
    char *data;
    size_t len;
    size_t cap;
};

struct SafeStr *ss_new(size_t cap) {
    struct SafeStr *s = malloc(sizeof(*s));
    s->data = malloc(cap);
    s->data[0] = '\0';
    s->len = 0;
    s->cap = cap;
    return s;
}

void ss_append(struct SafeStr *s, const char *src) {
    size_t add = strlen(src);
    if (s->len + add >= s->cap) return;  // prevent overflow
    memcpy(s->data + s->len, src, add + 1);
    s->len += add;
}

