#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct DynArray {
    int *data;
    size_t size;
    size_t capacity;
};

void da_init(struct DynArray *da, size_t cap) {
    da->data = malloc(cap * sizeof(int));
    da->size = 0;
    da->capacity = cap;
}

void da_push(struct DynArray *da, int val) {
    if (da->size >= da->capacity) {
        da->capacity *= 2;
        da->data = realloc(da->data, da->capacity * sizeof(int));
    }
    da->data[da->size++] = val;
}

int da_pop(struct DynArray *da) {
    if (da->size == 0) return -1;
    return da->data[--da->size];
}

void da_free(struct DynArray *da) {
    free(da->data);
    da->data = NULL;
    da->size = da->capacity = 0;
}

int main() {
    struct DynArray da;
    da_init(&da, 4);
    for (int i = 0; i < 10; i++)
        da_push(&da, i * i);
    for (size_t i = 0; i < da.size; i++)
        printf("%d ", da.data[i]);
    printf("\n");
    printf("Popped: %d\n", da_pop(&da));
    da_free(&da);
    return 0;
}

Hash Tables:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 16

struct Entry {
    char *key;
    int value;
    struct Entry *next;
};

unsigned long hash(const char *str) {
    unsigned long h = 5381;
    int c;
    while ((c = *str++))
        h = ((h << 5) + h) + c;
    return h;
}

void insert(struct Entry *table[TABLE_SIZE], char *k, int v) {
    struct Entry *e = malloc(sizeof(*e));
    e->key = strdup(k);
    e->value = v;
    int idx = hash(k) % TABLE_SIZE;
    e->next = table[idx];
    table[idx] = e;
}

int *lookup(struct Entry *table[TABLE_SIZE], const char *k) {
    int idx = hash(k) % TABLE_SIZE;
    for (struct Entry *e = table[idx]; e; e = e->next)
        if (strcmp(e->key, k) == 0)
            return &e->value;
    return NULL;
}

int main() {
    struct Entry *ht[TABLE_SIZE] = {0};
    insert(ht, "foo", 42);
    insert(ht, "bar", 99);

    int *v = lookup(ht, "bar");
    if (v) printf("bar = %d\n", *v);
    return 0;
}

