    SET_BIT(reg, 5);       // bit 5 set
    printf("Reg: 0x%02x\n", reg);  // 0x28

    CLR_BIT(reg, 3);
    printf("After clear: 0x%02x\n", reg);  // 0x20

    // Extract bits 4-6
    uint16_t val = 0b01101100;
    uint8_t extracted = GET_BITS(val, 6, 4);
    printf("Bits 6:4 = %u\n", extracted);  // 0b110 = 6

    // Swap nibbles
    uint8_t byte = 0xAB;
    uint8_t swapped = (byte << 4) | (byte >> 4);
    printf("Swapped: 0x%02x\n", swapped);  // 0xBA

