#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

void append(struct Node **head, int data) {
    struct Node *new = malloc(sizeof(struct Node));
    new->data = data;
    new->next = NULL;
    if (!*head) { *head = new; return; }
    struct Node *cur = *head;
    while (cur->next) cur = cur->next;
