Thread Pool Pattern:
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    void (*func)(void*);
    void *arg;
} Task;

typedef struct {
    Task *queue;
    int head, tail, size, count;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    int shutdown;
    pthread_t *threads;
    int thread_count;
} ThreadPool;

void *worker_loop(void *arg) {
    ThreadPool *pool = arg;
    while (1) {
        pthread_mutex_lock(&pool->mutex);
        while (pool->count == 0 && !pool->shutdown)
            pthread_cond_wait(&pool->not_empty, &pool->mutex);
        if (pool->shutdown) { pthread_mutex_unlock(&pool->mutex); return NULL; }
        Task task = pool->queue[pool->head];
        pool->head = (pool->head + 1) % pool->size;
        pool->count--;
        pthread_mutex_unlock(&pool->mutex);
        task.func(task.arg);
    }
}

void pool_submit(ThreadPool *pool, void (*func)(void*), void *arg) {
    pthread_mutex_lock(&pool->mutex);
    pool->queue[pool->tail].func = func;
    pool->queue[pool->tail].arg = arg;
    pool->tail = (pool->tail + 1) % pool->size;
    pool->count++;
    pthread_cond_signal(&pool->not_empty);
    pthread_mutex_unlock(&pool->mutex);
}
